 function edit(i:Item){I(i.id);N(i.name);L(i.location);Q(i.quantity);V(i.price);E(i.expiry);PurchaseDate(i.purchased||'');OpenedDate(i.opened||'');ScanConfidence(i.confidence);Brand(i.brand||'');Barcode(i.barcode||'');Category(i.category||'Other');Note(i.note||'');go('Inventory')}
 function changeStatus(i:Item,status:Item['status'],reason?:string){S(x=>({...x,items:x.items.map(j=>j.id===i.id?{...j,status}:j),events:[...x.events,addEvent(i,status,status==='discarded'?i.price*i.quantity:status==='consumed'?i.price*i.quantity:0,reason,i.quantity)]}));if(status==='consumed')award(5,'Artifact Rescuer');if(status==='discarded')award(1,'');B(status==='discarded'?'Recorded in Fridge Graveyard':'Inventory updated')}
