 async function lookupBarcode(code:string){if(!code.trim())return;LookupBusy(true);try{const r=await fetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json`);if(!r.ok)throw new Error('Product lookup unavailable');const d=await r.json();if(d.status!==1){B('No match in Open Food Facts. You can add the barcode and food name manually.');return}const p=d.product;N(p.product_name||'');Brand(p.brands||'');Barcode(code);Category(p.categories?.split(',')[0]||'Other');B(`Found ${p.product_name||'product'} in Open Food Facts. Review and save the fields.`)}catch{B('Open Food Facts lookup failed. Add the item manually or try again when connected.')}finally{LookupBusy(false)}}
 async function readReceipt(file?:File){if(!file)return;ScanBusy(true);OcrText('Loading receipt OCR…');SetReceiptDraft(null);try{const{createWorker}=await import('tesseract.js');const worker=await createWorker('eng');try{const result=await worker.recognize(file);OcrText(result.data.text);SetReceiptDraft(parseReceipt(result.data.text));B('OCR complete. Check every extracted field; nothing changes until you confirm selected items.')}finally{await worker.terminate()}}catch{OcrText('Receipt OCR did not load. You can still enter receipt items manually.');B('OCR is unavailable offline or the OCR engine could not load.')}finally{ScanBusy(false)}}
