 async function scanPhotoFiles(files:FileList|null){if(!files?.length)return;Detections([]);const incoming=Array.from(files);for(const f of incoming){if(!f.type.startsWith('image/'))continue;Photos(x=>[...x,URL.createObjectURL(f)])}B(`${incoming.length} photo${incoming.length===1?'':'s'} ready for manual review. No food detections are being claimed.`)}
 async function detectFood(){if(!photos.length){B('Add shelf photos before running recognition.');return}ScanBusy(true);Detections([]);B('Loading the optional TensorFlow.js model. First use downloads the model from Google-hosted public storage. Your photos are analyzed in this browser and are not uploaded.');try{const tf=await import('@tensorflow/tfjs');await tf.ready();const coco=await import('@tensorflow-models/coco-ssd');foodDetectorPromise??=coco.load({base:'lite_mobilenet_v2'});let model;try{model=await foodDetectorPromise}catch(error){foodDetectorPromise=null;throw error}ModelReady(true);const results:{label:string;confidence:number;photo:number;box:number[]}[]=[];for(let i=0;i<photos.length;i++){const img=new Image();img.src=photos[i];await new Promise<void>((resolve,reject)=>{img.onload=()=>resolve();img.onerror=()=>reject(new Error('Could not decode image'))});const found=await model.detect(img,20,.5);for(const x of found)results.push({label:x.class,confidence:x.score,photo:i+1,box:x.bbox})}Detections(results);const food=results.filter(x=>foodLabels.has(x.label));B(`${results.length} object boxes found; ${food.length} use a common-food label. Verify every result; this model misses many foods and can mislabel objects.`)}catch(e){B(`On-device recognition could not run: ${e instanceof Error?e.message:'model or browser unavailable'}. Continue with assisted manual review.`)}finally{ScanBusy(false)}}
