 function addShopping(name:string,source='Manual'){if(!name.trim())return;const key=name.trim().toLowerCase();if(s.shopping.some(i=>i.name.toLowerCase()===key&&!i.done)){B(`${name} is already on the list`);return}S(x=>({...x,shopping:[...x.shopping,{id:newId(),name:name.trim(),done:false,quantity:1,source}]}));B(`Added ${name} to shopping list`)}
